return resources.map(({ id, slots }) => {
  const blockingSlots = (blockingIdsByResource.get(id) ?? [])
    .flatMap((blockingId) => slotsByResource.get(blockingId) ?? [])
    .sort((a, b) => a.start.localeCompare(b.start) || a.id - b.id);
  const ownSlots = annotateConflicts(slots ?? [], blockingSlots);
  const visibleBlockingSlots: SlotDto[] = blockingSlots.map((slot) => ({
    ...slot,
    conflicts: [],
  }));

  return {
    resourceId: id,
    slots: [...ownSlots, ...visibleBlockingSlots].sort(
      (a, b) => a.start.localeCompare(b.start) || a.id - b.id,
    ),
  };
});

